function render(){if(!state.sheet)return;const x=range();for(let r=1;r<=ROWS;r++)for(let c=1;c<=COLS;c++){const a=addr(r,c),d=$('cell-'+a),v=display(a);d.textContent=v;d.className='cell'+(r>=x.r1&&r<=x.r2&&c>=x.c1&&c<=x.c2?' selected':'')+(r===state.focus.r&&c===state.focus.c?' active':'')+(String(v).startsWith('#')?' error':'')+(state.conflicts.has(a)?' conflict-cell':'');d.title=String(raw(a)).startsWith('=')?`${raw(a)} → ${v}`:''}const a=addr(state.focus.r,state.focus.c);$('nameBox').value=rangeAddress();$('selectionInfo').textContent=rangeAddress();if(document.activeElement!==$('formula'))$('formula').value=raw(a);$('formulaHelp').textContent=String(raw(a)).startsWith('=')?`Result: ${display(a)}`:'Type = to enter a formula';$('undo').disabled=!state.undo.length;$('redo').disabled=!state.redo.length;drawRemote()}
