function changesFromSaved(){const out=[],old=state.saved.sheets[0].cells,now=state.sheet.cells,keys=new Set([...Object.keys(old),...Object.keys(now)]);for(const a of keys)if(String(old[a]??'')!==String(now[a]??''))out.push({sheetId:state.sheet.id,address:a,value:String(now[a]??'')});return out}
async function save(){if(state.saving||!state.dirty)return;if(state.conflicts.size){setSaveState('Conflict','failed');showMessage('Resolve highlighted conflicts before saving. Your local values are preserved.',true);return}const changes=changesFromSaved();if(!changes.length){state.dirty=false;setSaveState('Saved','saved');return}state.saving=true;setSaveState('Saving…','saving');try{const res=await fetch(`/api/workbooks/${state.workbook.id}/save`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({baseRevision:state.revision,userId:state.userId,workbook:state.workbook,changes})});const data=await res.json();if(!res.ok){if(data.conflicts)for(const k of data.conflicts)state.conflicts.add(k.split(':').pop());throw Error(data.error||'Save failed')}state.revision=data.revision;state.saved=clone(data.workbook);state.workbook=clone(data.workbook);state.sheet=state.workbook.sheets[0];state.dirty=false;setSaveState('Saved','saved');$('revision').textContent=`Revision ${state.revision}`;render()}catch(e){setSaveState('Failed to save','failed');showMessage(e.message,true);render()}finally{state.saving=false}}
