function parseRangeText(s){const m=/^([A-Z]+[1-9]\d*)(?::([A-Z]+[1-9]\d*))?$/.exec(s.trim().toUpperCase());if(!m)return null;const a=parseAddr(m[1]),b=parseAddr(m[2]||m[1]);if(!a||!b||a.r>ROWS||b.r>ROWS||a.c>COLS||b.c>COLS)return null;return {r1:Math.min(a.r,b.r),r2:Math.max(a.r,b.r),c1:Math.min(a.c,b.c),c2:Math.max(a.c,b.c)} }
