function selectedTSV(){const x=range(),rows=[];for(let r=x.r1;r<=x.r2;r++){const row=[];for(let c=x.c1;c<=x.c2;c++)row.push(raw(addr(r,c)));rows.push(row.join('\t'))}return rows.join('\n')}
