function fill(direction){const x=range();if((direction==='down'&&x.r1===x.r2)||(direction==='right'&&x.c1===x.c2))return showMessage('Select a multi-cell range to fill');const changes={};if(direction==='down'){for(let c=x.c1;c<=x.c2;c++){const a=raw(addr(x.r1,c)),b=x.r1<x.r2?raw(addr(x.r1+1,c)):a,n1=Number(a),n2=Number(b),step=Number.isFinite(n1)&&Number.isFinite(n2)?n2-n1:0,start=step?x.r1+2:x.r1+1;for(let r=start;r<=x.r2;r++)changes[addr(r,c)]=String(a).startsWith('=')?shiftFormula(a,r-x.r1,0):step?String(n1+step*(r-x.r1)):a}}else{for(let r=x.r1;r<=x.r2;r++){const a=raw(addr(r,x.c1)),b=x.c1<x.c2?raw(addr(r,x.c1+1)):a,n1=Number(a),n2=Number(b),step=Number.isFinite(n1)&&Number.isFinite(n2)?n2-n1:0,start=step?x.c1+2:x.c1+1;for(let c=start;c<=x.c2;c++)changes[addr(r,c)]=String(a).startsWith('=')?shiftFormula(a,0,c-x.c1):step?String(n1+step*(c-x.c1)):a}}action(changes,direction==='down'?'Fill down':'Fill right')}
function findMatches(){const q=$('findText').value.toLowerCase();if(!q)return[];return Object.keys(state.sheet.cells).filter(a=>String(raw(a)).toLowerCase().includes(q)).sort((a,b)=>{const x=parseAddr(a),y=parseAddr(b);return x.r-y.r||x.c-y.c})}
