function formulaHints(){const v=$('formula').value,box=$('suggestions');if(!v.startsWith('=')){box.style.display='none';clearReferences();return}const m=/([A-Za-z]*)$/.exec(v),q=m?m[1].toUpperCase():'';const list=FUNCS.filter(f=>f.startsWith(q));if(list.length){const rect=$('formula').getBoundingClientRect();box.style.left=rect.left+'px';box.style.top=rect.bottom+'px';box.innerHTML=list.map(f=>`<div class="suggestion" data-f="${f}">${f} — ${f==='AVG'?'average':f.toLowerCase()} values</div>`).join('');box.style.display='block'}else box.style.display='none';showReferences(v)}
