async function cellHistory(){const a=addr(state.focus.r,state.focus.c),res=await fetch(`/api/workbooks/${state.workbook.id}/history?sheetId=${state.sheet.id}&address=${a}`),items=await res.json();openDialog(`History for ${a}`,items.length?items.map(x=>`<div class="historyItem"><b>${esc(x.userName)}</b> changed <code>${esc(x.previousValue||'(blank)')}</code> to <code>${esc(x.newValue||'(blank)')}</code><div class="muted">Revision ${x.revision} · ${new Date(x.changedAt).toLocaleString()}</div></div>`).join(''):'<p>No saved changes for this cell.</p>')}
